package com.examservice.presentation.response;import com.examservice.domain.model.*;import java.time.Instant;import java.util.*;public final class ExamViews{private ExamViews(){}public record MatrixView(UUID id,String name,String facultyId,UUID subjectId,int totalQuestions,List<ExamMatrixRule>rules,Instant createdAt,Instant updatedAt){public static MatrixView from(ExamMatrix m){return new MatrixView(m.id(),m.name(),m.facultyId(),m.subjectId(),m.totalQuestions(),m.rules(),m.createdAt(),m.updatedAt());}}public record TemplateView(UUID id,String name,String facultyId,UUID matrixId,String header,String instructions,Instant createdAt){public static TemplateView from(ExamTemplate t){return new TemplateView(t.id(),t.name(),t.facultyId(),t.matrixId(),t.header(),t.instructions(),t.createdAt());}}public record VersionView(UUID id,int version,List<ExamQuestionReference>questions,Instant createdAt){static VersionView from(ExamVersion v){return new VersionView(v.id(),v.versionNumber(),v.questions(),v.createdAt());}}public record ExamView(UUID id,String name,String facultyId,UUID subjectId,UUID matrixId,UUID templateId,List<VersionView>versions,Instant createdAt,Instant updatedAt){public static ExamView from(Exam e){return new ExamView(e.id(),e.name(),e.facultyId(),e.subjectId(),e.matrixId(),e.templateId(),e.versions().stream().map(VersionView::from).toList(),e.createdAt(),e.updatedAt());}}}
